const slots = [
  ...(entity.attributes.raw_today || []),
  ...(entity.attributes.raw_tomorrow || []),
];
const pricesByStart = new Map();
for (const slot of slots) {
  const timestamp = new Date(slot.start).getTime();
  const value = Number(slot.value);
  if (Number.isFinite(timestamp) && Number.isFinite(value)) {
    pricesByStart.set(timestamp, value);
  }
}
return [...pricesByStart.entries()].sort((left, right) => left[0] - right[0]);

const dayStart = new Date();
dayStart.setHours(0, 0, 0, 0);
const rangeEnd = new Date(dayStart);
rangeEnd.setDate(rangeEnd.getDate() + 2);
const value = Number(entity.state);
return [[dayStart.getTime(), value], [rangeEnd.getTime(), value]];
